{"path": "/app/bin/crosstabs.py", "content": "#!/usr/bin/env python3
"""Residents survey: response summary and weighted crosstabs.

Usage: python3 crosstabs.py INPUT_DIR OUTPUT_FILE
Rules: see /app/docs (overview.md first). Standard library only.
"""
import csv
import io
import json
import math
import os
import sys
from datetime import datetime, timedelta, timezone
from fractions import Fraction


# ---------------------------------------------------------------- reading

def read_export(path):
    with open(path, "rb") as f:
        data = f.read()
    text = data.decode("utf-8")
    if text.startswith("\ufeff"):
        text = text[1:]
    first = text.replace("\r\n", "\n").replace("\r", "\n").split("\n", 1)[0]
    delim = ","
    best = -1
    for d in (",", ";", "\t"):
        n = first.count(d)
        if n > best:
            best, delim = n, d
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delim, quotechar='"')
    header = None
    rows = []
    for cells in reader:
        cells = [c.strip() for c in cells]
        if header is None:
            if not any(cells):
                continue
            header = cells
            continue
        if not any(cells):
            continue
        row = {}
        for i, name in enumerate(header):
            v = cells[i] if i < len(cells) else ""
            if name in row and not v:
                continue
            row[name] = v if v else None
        rows.append(row)
    return rows


def read_all_rows(input_dir):
    exp = os.path.join(input_dir, "exports")
    rows = []
    if not os.path.isdir(exp):
        return rows
    for name in sorted(os.listdir(exp)):
        p = os.path.join(exp, name)
        if name.endswith(".csv") and os.path.isfile(p):
            rows.extend(read_export(p))
    return rows


# ---------------------------------------------------------------- parsing

def parse_offset(s):
    sign = -1 if s[0] == "-" else 1
    hh, mm = s[1:].split(":")
    return timezone(sign * timedelta(hours=int(hh), minutes=int(mm)))


def parse_time(value, meta):
    if value is None:
        return datetime.min.replace(tzinfo=timezone.utc)
    if meta.get("submitted_format") == "local":
        dt = datetime.strptime(value, "%Y-%m-%d %H:%M:%S")
        return dt.replace(tzinfo=parse_offset(meta.get("utc_offset", "+00:00")))
    v = value
    if v.endswith("Z") or v.endswith("z"):
        v = v[:-1] + "+00:00"
    dt = datetime.fromisoformat(v)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def parse_duration(value, meta):
    if value is None:
        return None
    if meta.get("duration_format") == "clock":
        parts = [int(p) for p in value.split(":")]
        secs = 0
        for p in parts:
            secs = secs * 60 + p
        return secs
    return int(float(value)) if not value.lstrip("+-").isdigit() else int(value)


def parse_int(value, default=0):
    if value is None:
        return default
    try:
        return int(value)
    except ValueError:
        return int(float(value))


# ---------------------------------------------------------------- answers

def to_code(value, recode):
    if recode is not None:
        return recode[value]
    return int(value)


def read_answer(q, entry, row):
    """Valid answer: a code (single/age), a frozenset of codes (multi) or None."""
    qtype = q["type"]
    if qtype == "single":
        v = row.get(entry["column"])
        if v is None:
            return None
        code = to_code(v, entry.get("recode"))
        return None if is_missing(q, code) else code
    if qtype == "age":
        v = row.get(entry["column"])
        if v is None:
            return None
        src = entry.get("source")
        if src == "band":
            code = to_code(v, entry.get("recode"))
            return code
        age = int(v)
        if src == "birth_year":
            age = entry["_ref_year"] - age
        for b in q["bands"]:
            if b["min"] <= age <= b["max"]:
                return b["code"]
        return None
    # multi
    chosen = set()
    recode = entry.get("recode")
    if "columns" in entry:
        for code, col in entry["columns"].items():
            if row.get(col) == "1":
                chosen.add(int(code))
    else:
        v = row.get(entry["column"])
        if v is not None:
            for el in v.split(entry["separator"]):
                el = el.strip()
                if el:
                    chosen.add(to_code(el, recode))
    if not chosen:
        return None
    opts = {o["code"]: o for o in q["options"]}
    excl = {c for c in chosen if opts[c].get("exclusive")}
    if len(excl) < len(chosen):
        chosen -= excl
    elif len(chosen) >= 2:
        return None
    chosen = {c for c in chosen if not opts[c].get("missing")}
    return frozenset(chosen) if chosen else None


def is_missing(q, code):
    for o in q.get("options", []):
        if o["code"] == code:
            return bool(o.get("missing"))
    return False


def holds(answer, codes):
    if answer is None:
        return False
    if isinstance(answer, frozenset):
        return any(c in answer for c in codes)
    return answer in codes


# ---------------------------------------------------------------- main

def median_fraction(values):
    s = sorted(values)
    n = len(s)
    if n % 2:
        return Fraction(s[n // 2])
    return Fraction(s[n // 2 - 1] + s[n // 2], 2)


def rnd(x):
    if x is None:
        return None
    r = round(x + 0.0, 2)
    return r + 0.0 if r != 0 else 0.0


def main(input_dir, output_file):
    def load(name):
        with open(os.path.join(input_dir, name), encoding="utf-8-sig") as f:
            return json.load(f)

    codebook = load("codebook.json")
    weighting = load("weighting.json")
    plan = load("tables.json")
    versions = codebook["versions"]
    vkeys = list(versions.keys())
    ref_year = int(str(codebook["reference_date"])[:4])
    min_page = codebook.get("partial_min_page", 0)
    questions = codebook["questions"]
    qmap = {q["id"]: q for q in questions}
    for q in questions:
        for e in q["versions"].values():
            e["_ref_year"] = ref_year

    # 1. read rows
    recs = []
    stats = {k: {"rows": 0, "duplicates": 0, "short_partials": 0, "speeders": 0,
                 "complete": 0, "partial": 0} for k in vkeys}
    for row in read_all_rows(input_dir):
        vk = row.get("form_version")
        if vk not in versions:
            continue
        meta = versions[vk]["meta"]
        stats[vk]["rows"] += 1
        complete = row.get(meta["status"]) == meta["complete"]
        recs.append({
            "row": row, "v": vk, "meta": meta,
            "id": row.get(meta["id"]),
            "complete": complete,
            "time": parse_time(row.get(meta["submitted"]), meta),
            "duration": parse_duration(row.get(meta["duration"]), meta),
            "last_page": parse_int(row.get(meta["last_page"])),
        })

    # 2. one row per respondent
    best = {}
    for r in recs:
        cur = best.get(r["id"])
        if cur is None or (r["complete"], r["time"]) > (cur["complete"], cur["time"]):
            best[r["id"]] = r
    winners = {id(r) for r in best.values()}
    kept = []
    for r in recs:
        if id(r) in winners:
            kept.append(r)
        else:
            stats[r["v"]]["duplicates"] += 1

    # 3. short partials
    kept2 = []
    for r in kept:
        if not r["complete"] and r["last_page"] < min_page:
            stats[r["v"]]["short_partials"] += 1
        else:
            kept2.append(r)
    kept = kept2

    # 4. speeders
    medians = {}
    for vk in vkeys:
        durs = [r["duration"] for r in kept
                if r["v"] == vk and r["complete"] and r["duration"] is not None]
        if durs:
            medians[vk] = median_fraction(durs)
    kept3 = []
    for r in kept:
        m = medians.get(r["v"])
        if (r["complete"] and r["duration"] is not None and m is not None
                and r["duration"] * 5 < m * 2):
            stats[r["v"]]["speeders"] += 1
        else:
            kept3.append(r)
    kept = kept3
    for r in kept:
        stats[r["v"]]["complete" if r["complete"] else "partial"] += 1

    # 5. routing and answers
    for r in kept:
        answers = {}
        asked = {}

        def is_asked(qid, r=r, answers=answers, asked=asked):
            if qid in asked:
                return asked[qid]
            asked[qid] = False
            q = qmap[qid]
            entry = q["versions"].get(r["v"])
            ok = entry is not None
            if ok and not r["complete"] and entry["page"] > r["last_page"]:
                ok = False
            if ok and q.get("ask_if"):
                cond = q["ask_if"]
                dep = cond["question"]
                ok = is_asked(dep) and holds(answers.get(dep), cond["codes"])
            asked[qid] = ok
            if ok:
                answers[qid] = read_answer(q, entry, r["row"])
            return ok

        for q in questions:
            is_asked(q["id"])
        r["answers"] = answers

    n = len(kept)

    # 6. weighting
    weights = [1.0] * n
    if n:
        dims = []
        for d in weighting["dimensions"]:
            qid = d["question"]
            present = {r["answers"].get(qid) for r in kept}
            targets = {}
            for code, t in d["targets"].items():
                if int(code) in present:
                    targets[int(code)] = float(t)
            total = sum(targets.values())
            if not targets or total <= 0:
                continue
            shares = {c: t / total for c, t in targets.items()}
            cats = [r["answers"].get(qid) if r["answers"].get(qid) in shares else None
                    for r in kept]
            dims.append((shares, cats))
        for _ in range(weighting.get("max_iterations", 100)):
            done = True
            for shares, cats in dims:
                T = math.fsum(w for w, c in zip(weights, cats) if c is not None)
                W = {c: 0.0 for c in shares}
                for w, c in zip(weights, cats):
                    if c is not None:
                        W[c] += w
                f = {}
                for c in shares:
                    f[c] = shares[c] * T / W[c] if W[c] > 0 else 1.0
                    if abs(f[c] - 1) > weighting.get("tolerance", 1e-10):
                        done = False
                for i, c in enumerate(cats):
                    if c is not None:
                        weights[i] *= f[c]
            if done:
                break
        m = math.fsum(weights) / n
        hi, lo = weighting["cap"] * m, weighting["floor"] * m
        weights = [min(max(w, lo), hi) for w in weights]
        s = math.fsum(weights)
        weights = [w * n / s for w in weights]

    # 7. summary
    summary = {
        "versions": [dict(version=k, **stats[k]) for k in vkeys],
        "respondents": n,
    }
    if n:
        sw = math.fsum(weights)
        sw2 = math.fsum(w * w for w in weights)
        summary["effective_n"] = rnd(sw * sw / sw2)
        summary["weight_min"] = rnd(min(weights))
        summary["weight_max"] = rnd(max(weights))
    else:
        summary["effective_n"] = None
        summary["weight_min"] = None
        summary["weight_max"] = None

    # 8. tables
    columns = [("total", None, None)]
    for qid in plan["banner"]:
        q = qmap[qid]
        items = q["bands"] if q["type"] == "age" else [o for o in q["options"] if not o.get("missing")]
        for o in items:
            if o.get("missing"):
                continue
            columns.append((f"{qid}:{o['code']}", qid, o["code"]))

    tables = []
    for t in plan["tables"]:
        q = qmap[t["question"]]
        opts = [o for o in q["options"] if not o.get("missing")]
        nets = t.get("nets") or []
        base_idx = [i for i, r in enumerate(kept) if r["answers"].get(q["id"]) is not None]
        cols = []
        for cid, bq, bcode in columns:
            idx = [i for i in base_idx
                   if bq is None or kept[i]["answers"].get(bq) == bcode]
            wb = math.fsum(weights[i] for i in idx)
            values = {}
            if not idx or wb == 0:
                for o in opts:
                    values[str(o["code"])] = None
                for nt in nets:
                    values[nt["id"]] = None
                if t.get("mean"):
                    values["mean"] = None
            else:
                for o in opts:
                    c = o["code"]
                    values[str(c)] = rnd(100 * math.fsum(
                        weights[i] for i in idx if holds(kept[i]["answers"][q["id"]], [c])) / wb)
                for nt in nets:
                    values[nt["id"]] = rnd(100 * math.fsum(
                        weights[i] for i in idx
                        if holds(kept[i]["answers"][q["id"]], nt["codes"])) / wb)
                if t.get("mean"):
                    score = {o["code"]: o["score"] for o in opts}
                    values["mean"] = rnd(math.fsum(
                        weights[i] * score[kept[i]["answers"][q["id"]]] for i in idx) / wb)
            cols.append({"column": cid, "base": len(idx),
                         "weighted_base": rnd(wb) if idx else 0, "values": values})
        tables.append({"table": t["id"], "columns": cols})

    out = {"survey": codebook["survey"], "summary": summary, "tables": tables}
    d = os.path.dirname(os.path.abspath(output_file))
    os.makedirs(d, exist_ok=True)
    with open(output_file, "w", encoding="utf-8") as f:
        json.dump(out, f, indent=1)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.stderr.write("usage: crosstabs.py INPUT_DIR OUTPUT_FILE\n")
        sys.exit(2)
    main(sys.argv[1], sys.argv[2])
"}
